namespace InventoryApp.Services;

public record EquipmentItem(
    int Id,
    string Name,
    string Location,
    DateTime LastInspected);

public class EquipmentService
{
    public async Task<List<EquipmentItem>> GetEquipmentAsync()
    {
        // Simulate a real data-fetch delay.
        await Task.Delay(500);

        return new List<EquipmentItem>
        {
            new(1, "Forklift A",        "Warehouse 1",  new DateTime(2026, 6, 10)),
            new(2, "Conveyor Belt B",    "Warehouse 2",  new DateTime(2026, 5, 22)),
            new(3, "Pallet Jack C",      "Loading Dock",  new DateTime(2026, 7, 1)),
            new(4, "Hydraulic Press D",  "Shop Floor",    new DateTime(2026, 4, 15)),
            new(5, "Drill Press E",      "Shop Floor",    new DateTime(2026, 3, 30)),
            new(6, "Lathe F",            "Machine Room",  new DateTime(2026, 6, 25)),
            new(7, "Crane G",            "Yard",          new DateTime(2026, 2, 18)),
            new(8, "Compressor H",       "Utility Room",  new DateTime(2026, 7, 5)),
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private const string PersistenceKey = "equipment-items";
    private List<EquipmentItem>? _items;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // Register a callback so that during prerender the framework
        // serialises the data into the page HTML.
        _subscription = ApplicationState.RegisterOnPersisting(PersistData);

        // If persisted state exists (interactive reconnect after prerender),
        // reuse it instead of calling the service a second time.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                PersistenceKey, out var restored))
        {
            _items = restored;
        }
        else
        {
            _items = await EquipmentSvc.GetEquipmentAsync();
        }
    }

    private Task PersistData()
    {
        ApplicationState.PersistAsJson(PersistenceKey, _items);
        return Task.CompletedTask;
    }

    public void Dispose() => _subscription.Dispose();
}

